package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.applicant.domain.PositionApplication; import com.primehr.rsp.domain.RspAuditedEntity; import com.primehr.rsp.screening.domain.ScreeningCase; import jakarta.persistence.*; import org.hibernate.annotations.Nationalized; import java.time.*; import java.util.*;
@Entity @Table(name="rsp_evaluation_candidate",uniqueConstraints=@UniqueConstraint(name="uk_rsp_evaluation_candidate_application",columnNames={"agency_id","proceeding_id","application_id"}))
public class EvaluationCandidate extends RspAuditedEntity {
 public enum Status { ADMITTED }
 @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="proceeding_id",nullable=false) private EvaluationProceeding proceeding; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="application_id",nullable=false) private PositionApplication application; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="screening_case_id",nullable=false) private ScreeningCase screeningCase; @Column(name="applicant_id",nullable=false,length=36) private String applicantId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Status status; @Column(name="current_application_key",length=36) private String currentApplicationKey; @Column(name="application_version",nullable=false) private int applicationVersion; @Column(name="screening_case_revision",nullable=false) private int screeningCaseRevision; @Nationalized @Column(name="application_snapshot",nullable=false,length=32000) private String applicationSnapshot; @Nationalized @Column(name="screening_snapshot",nullable=false,length=32000) private String screeningSnapshot; @Column(name="application_fingerprint",nullable=false,length=64) private String applicationFingerprint; @Column(name="screening_fingerprint",nullable=false,length=64) private String screeningFingerprint; @Column(name="admitted_by",nullable=false,length=100) private String admittedBy; @Column(name="admitted_at",nullable=false) private Instant admittedAt;
 protected EvaluationCandidate(){}
 public EvaluationCandidate(String agency,EvaluationProceeding proceeding,PositionApplication application,ScreeningCase screening,String appSnapshot,String screenSnapshot,String appFingerprint,String screenFingerprint,String actor,Instant at){super(agency);this.proceeding=Objects.requireNonNull(proceeding);this.application=Objects.requireNonNull(application);screeningCase=Objects.requireNonNull(screening);applicantId=application.getApplicantId();status=Status.ADMITTED;currentApplicationKey=application.getId();applicationVersion=application.getApplicationVersion();screeningCaseRevision=screening.getCaseRevision();applicationSnapshot=requiredText(appSnapshot,"applicationSnapshot");screeningSnapshot=requiredText(screenSnapshot,"screeningSnapshot");applicationFingerprint=requiredText(appFingerprint,"applicationFingerprint");screeningFingerprint=requiredText(screenFingerprint,"screeningFingerprint");admittedBy=requiredText(actor,"actor");admittedAt=Objects.requireNonNull(at);}
 public EvaluationProceeding getProceeding(){return proceeding;} public PositionApplication getApplication(){return application;} public ScreeningCase getScreeningCase(){return screeningCase;} public String getApplicantId(){return applicantId;} public Status getStatus(){return status;} public int getApplicationVersion(){return applicationVersion;} public int getScreeningCaseRevision(){return screeningCaseRevision;} public String getApplicationSnapshot(){return applicationSnapshot;} public String getScreeningSnapshot(){return screeningSnapshot;} public String getApplicationFingerprint(){return applicationFingerprint;} public String getScreeningFingerprint(){return screeningFingerprint;} public String getAdmittedBy(){return admittedBy;} public Instant getAdmittedAt(){return admittedAt;}
}
